import json

patch = []
def setv(tensor, index, value):
    if value != 0:
        patch.append({"op":"set", "tensor":tensor, "index":list(index), "value":value})

# Preserve the input channels throughout the four stages.
for i in range(10):
    setv("w0", (i, i), 1)
    for layer in range(1, 4):
        setv(f"w{layer}", (i, i), 1)

# The class-1 function is the OR of four Boolean terms:
# ~x0, x4 & x6, ~x3 & ~x9, x2 & x7 & ~x6.
terms = [
    (10, {0:-1}, 1),
    (13, {4:1, 6:1}, -1),
    (16, {3:-1, 9:-1}, 1),
    (19, {2:1, 7:1, 6:-1}, -1),
]
for channel, coefficients, bias in terms:
    for feature, coefficient in coefficients.items():
        setv("w0", (channel, feature), coefficient)
    setv("b0", (channel,), bias)
    for layer in range(1, 4):
        setv(f"w{layer}", (channel, channel), 1)
    setv("out", (1, channel), 1)

setv("bias", (0,), 0.5)
sub = {"patch": patch}
print(check_submission(sub))
with open("/work/submission.json", "w") as f:
    json.dump(sub, f)
